	DELVELOG_LBL_DEATHS = "Morts :",
	DELVELOG_LBL_KEY = "Clé",
	DELVELOG_TOTAL_TIME = "Temps total :",
	INFO_DRAWER_BODY_DELVELOG = "Le Journal des plongées enregistre chaque plongée de Minuit que tu termines sur ce personnage. Clique sur une plongée pour déplier ses dernières runs. Chaque run indique le palier, le temps, les morts, si tu as utilisé une Clé de coffre restaurée et le boss final. Le suivi tourne en arrière-plan ; cet onglet n'a pas besoin d'être ouvert.",
	TAB_WORLD = "Void & Rituals",
	TAB_EVENTS = "Événements",
	EVENTS_SUBTITLE = "Tous les événements de monde de Midnight : ce qui se passe maintenant et ce qui arrive dans les 24 prochaines heures. Cliquez sur un événement actif pour tracer un itinéraire ; survolez pour savoir de quoi il s'agit et ce qu'il rapporte.",
	EVENTS_NONE = "Aucun événement de monde visible pour le moment — le planificateur charge peut-être encore. Réessayez dans quelques secondes.",
	WORLD_EVENTS_HEADER = "Événements de monde",
	WORLD_EVENTS_NOW = "En cours",
