	EVENT_INFO_REWARD_LABEL = "Récompenses :",
	EVENT_INFO_CLICK_HINT = "Cliquez pour tracer un itinéraire.",
	EVENT_INFO_STORMARION_DESC = "Défense de tour dans Voidstorm à la Stormarion Citadel — commence toutes les 30 minutes. Repoussez les vagues avec tout le monde dans la zone.",
	EVENT_INFO_STORMARION_REWARD = "Par run : Stormarion Core, Voidlight Marl, or et équipement vétéran. Le coffre hebdomadaire 'Stand Your Ground' a une chance de donner la monture Contained Stormarion Defender et une mascotte, plus de la renommée auprès de The Singularity.",
	EVENT_INFO_HARANIR_DESC = "Un événement narratif plus calme à Harandar. Prenez la quête hebdomadaire 'Lost Legends', choisissez une relique et parcourez sa chaîne de quêtes (jouable en solo).",
	EVENT_INFO_HARANIR_REWARD = "Un coffre hebdomadaire, de la réputation Hara'ti et un objet de décoration lié à votre relique. Collectez toutes les histoires de reliques pour le titre 'Chronicler of the Haranir'.",
	EVENT_WEEKLY_DONE = "hebdo terminée",
	EVENT_WEEKLY_TURNIN = "hebdo : à rendre !",
	EVENT_WEEKLY_ACTIVE = "hebdo : en cours",
	EVENT_WEEKLY_TODO = "hebdo disponible",
	EVENT_WEEKLY_LABEL = "Hebdo :",
	MODEL_PREVIEW_HINT = "Glisser pour tourner · molette pour zoomer",
	MODEL_PREVIEW_SPIN = "Rotation",
	MODEL_PREVIEW_RESET = "Réinit.",
	MODEL_PREVIEW_REWARDS_HINT = "Maj+clic : aperçu des récompenses",
	WORLD_SUBTITLE = "Contenu de monde hebdomadaire de Midnight à Quel'Thalas. Un Site rituel est actif dans une zone et le Vide attaque une autre — les deux partagent le hub du Bazar, les Distinctions de terrain et la renommée.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals réunit les deux systèmes de monde tournants de Midnight. Sites rituels : perturbe le site actif (icône violette) à son obélisque. Assauts du Vide : nettoie les Frappes du Vide dans la zone active pour déclencher une Incursion du Vide. Les deux donnent des Distinctions de terrain, remplissent ta rangée de monde de la Grande Chambre forte et alimentent la renommée commune des Sites rituels. Les deux quêtes hebdo se prennent au hub du Bazar à Lune-d'argent.",
	TAB_REFERENCE = "Bases",
	REF_PANEL_INTRO = "Explications simples sur les systèmes de fin de partie. D'autres sujets arriveront ici.",
	INFO_DRAWER_BODY_REFERENCE = "Guides pour débutants : Crests, où les dépenser et bonus de bataillon. D'autres sujets (métiers, etc.) suivront.",
	TAB_SMC = "Silvermoon City",
	TAB_PROFESSIONS = "Métiers",
	TAB_GUIDE = "Guides de mise à niveau",
	TAB_MACROS = "Macro",
	TAB_CONSUMABLES = "Consommables",
	TAB_ACADEMY = "Académie de rôle",
	TAB_TOOLBOX = "Boîte à outils",
	-- Articles codex du patch 12.0.7
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns : Naigtal & Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Un portail dans le Voidstorm (Screaming Ridge) mène vers l'un des deux mondes du Vide en rotation : Naigtal le fongique ou Val le glacial. Chacun propose des expéditions mondiales, des rares, des événements de zone et un boss mondial (Nexus-Captain Leth'ir / Imperator Pertinax). L'hebdomadaire Showdown octroie une Riftstalker's Cache et compte pour la rangée World du Grand Coffre. La Heroic World Tier optionnelle augmente difficulté et récompenses — choix au portail. Départ : Riftblade Maella à Lune-d'argent.",
	CODEX_127_SPOREFALL_TITLE = "Raid Sporefall (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Raid à un boss à Harandar : Rotmire, un géant fongique. Même palier Saison 1 avec des niveaux d'objet supérieurs (LFR 259 / Normal 272 / Héroïque 285 / Mythique 298) ; le Mythique est flexible de 15 à 25 joueurs. Récupérez un Delicious Sporesnack une fois par semaine, peu importe la difficulté — quatre au total achètent la monture Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio & Runes (12.0.7)",
	CODEX_127_FOLIO_BODY = "Nouveau système de puissance sans emplacement d'équipement. Débloqué via la campagne du Sunstrider Omnium avec le magistère Umbric et le grand magistère Rommath à Quel'Danas. Chaque semaine, la quête 'Seeking Knowledge' donne un Mote of Omnial Inquiry pour ouvrir l'une des cinq rangées de runes ; les runes s'échangent librement hors combat.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30 juin - 11 août)",
	CODEX_127_TIMEWAYS_BODY = "Marathon des Marcheurs du temps avec six donjons Dragonflight. Faites quatre donjons dans la semaine pour le buff Mastery de la semaine ; obtenez Mastery sur quatre semaines distinctes pour la monture Spawn of Vyranoth.",
	CODEX_127_RITUALRENOWN_TITLE = "Renom des Sites rituels (12.0.7)",
	CODEX_127_RITUALRENOWN_BODY = "Les Sites rituels ont une voie de Renom liée au compte (8 rangs) dans la fenêtre Journeys. Monter en rang enrichit chaque site : Regeneration Orbs soignants, puis ennemis rares (rang 4), autels de bonus (rang 5), plus grands trésors (rang 7) et élites rares (rang 8) — tous avec du butin supplémentaire. Cela débloque aussi des articles chez les vendeurs de Lune-d'argent : déco d'habitat du Vide (rang 3, Rae'ana), familiers (rang 6, Sergeant Vornin) et la monture Void-Touched Hawkstrider (rang 8, Sergeant Vornin). Chaque récompense est liée au bataillon (Warband), votre progression compte donc pour tout le compte. Cliquez sur les Loa Shrines lumineux dans un site pour un buff de stat de 60 minutes (p. ex. +10% de coup critique).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "En cours de développement",
	TAB_BETA_TOOLTIP_BODY = "Cet onglet est en beta précoce — le contenu est incomplet, peut changer souvent et n'est pas prêt pour un usage complet.",
	TAB_ADDONS = "Modules complémentaires",
	SEARCH_CHAT_TAB_ACADEMY = "Onglet ouvert : Académie de rôle",
	ACADEMY_SUBTITLE = "Courte masterclass sur le tanking et la guérison en groupe : état d'esprit, cases à cocher de préparation et rampe douce vers les donjons. Pas un guide d'analyse.",
	ACADEMY_TRACK_TANK = "Piste de char",
	ACADEMY_TRACK_HEAL = "Piste de guérison",
	ACADEMY_CLASS_FMT = "Connecté : %s - %s (ouvre Macros / Consommables / Guides depuis la barre latérale)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macros ouvertes pour %s - %s. Regarde aussi Consommables pour flacons et pots.",
	ACADEMY_PREF_TITLE = "Checklist avant de partir (coche quand tu es prêt)",
	ACADEMY_PREF_HINT = "Les coches sont enregistrées dans tes paramètres. Ouvre l'onglet correspondant dans la barre latérale quand tu te prépares.",
	ACADEMY_PREF_TANK_INTERRUPT = "Macro d'interruption sur ma barre (onglet Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Un prêt défensif (onglet Guides -> Défensifs ou En groupes)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flacon / pot prêt (onglet Consommables)",
	ACADEMY_PREF_TANK_TAUNT = "Je connais ma clé de provocation (test factice une fois)",
	ACADEMY_PREF_HEAL_MACROS = "Survol de la souris / macros de guérison de focus (onglet Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Défensive personnelle sur la barre (Guides -> Défensives ou En groupes)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Pot / flacon de mana (onglet Consommables)",
	ACADEMY_PREF_HEAL_PRACTICE = "J'ai pratiqué le survol de soins sur un ami une fois.",
	ACADEMY_TANK_INTRO_TITLE = "Esprit de tank",
	ACADEMY_TANK_INTRO_BODY = "Ton job : donner le rythme et capter l'aggro — pas topper le compteur de dégâts.\n\nUn pull régulier bat une rotation parfaite sur un groupe mort. Dis « pull dans 3 » à voix haute si ça aide.",
	ACADEMY_TANK_PULL_TITLE = "Pendant un pull (10 premières secondes)",
	ACADEMY_TANK_PULL_BODY = "1. Prends le pack (provoc/menace).\n2. Tourne les ennemis loin du groupe quand tu peux.\n3. Utilise une défensive si les dégâts montent — garde la deuxième pour « oh non ».\n4. Interromps le sort qui fait le plus mal (souvent soin ou gros coup).\n\nTu n'as pas besoin de tout mettre en cooldown tout de suite.",
	ACADEMY_TANK_WIPE_TITLE = "Quand ça tourne mal",
	ACADEMY_TANK_WIPE_BODY = "Un wipe, c'est des données, pas un verdict. Demande-toi : « Trop en avance ? » ou « J'ai gardé une défensive ? »\n\nRépare, mange, réessaie.",
	ACADEMY_TANK_DUNGEON_TITLE = "Ton premier donjon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Commence en normal avec des amis ou la guilde si tu peux. Pull doucement — deux petits packs valent mieux qu'une longue chaîne.\n\nSurveille le mana du soigneur ; pause entre les pulls. Demander un CC ou « pas de gros pull » est ok.",
	ACADEMY_TANK_RAID_TITLE = "Raids et LFR (plus tard)",
	ACADEMY_TANK_RAID_BODY = "LFR est l'intro raid douce : indulgent, beaucoup de soigneurs. Focus sur le timing des provocs boss et rester au bon endroit.\n\nLe tank mythique raid n'est pas l'étape suivante — d'abord le confort en héroïque/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Chat de groupe",
	ACADEMY_CHAT_HINT = "Clique une ligne ou l'icône copier, puis Ctrl+C pour coller dans le chat de groupe.",
	ACADEMY_CHAT_COPY_TIP = "Sélectionne cette ligne (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Tank en apprentissage — allez doucement svp.\"\n\"Pull dans 3...\"\n\"Pause mana.\"\n\"Inter sur [nom du sort] — je le prends après.\"\n\"Encore un essai — je connais ce pull.\"",
	ACADEMY_TANK_LADDER_TITLE = "Échelle d'anxiété (ordre conseillé)",
	ACADEMY_TANK_LADDER_BODY = "1. Élites monde ouvert avec un ami\n2. Gouffres (petite instance — onglet Gouffres)\n3. Donjon normal avec des gens de confiance\n4. Héroïque / LFR quand tu es à l'aise\n\nSaute une étape jusqu'à que ce soit ennuyeux, pas effrayant.",
	ACADEMY_TANK_BOTH_TITLE = "Tu apprends aussi à soigner ?",
	ACADEMY_TANK_BOTH_BODY = "Super — mais choisis un rôle principal en donjon un moment. Entraîne l'autre en gouffres ou en monde ouvert.\n\nTank + heal dans le même M+ pug double le stress ; maîtriser un rôle d'abord donne confiance pour le second.",
	ACADEMY_HEAL_INTRO_TITLE = "État d'esprit soigneur",
	ACADEMY_HEAL_INTRO_BODY = "Tu n'es pas responsable de tout le monde à 100 % PV tout le temps.\n\nTon job : triage — garder le tank en vie, sauver celui qui va mourir, puis le reste. Un peu de dégâts est normal — le overheal paniqué vide le mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (qui en premier ?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Toi (si tu meurs — un soigneur mort ne soigne personne)\n2. Tank (si le pack est encore sur lui)\n3. Quiconque sous ~40 % ou avec un debuff mortel\n4. Le reste avec des soins efficaces\n\nGros soin après gros dégâts ; petits soins entre les événements.",
	ACADEMY_HEAL_WIPE_TITLE = "Quand ça tourne mal",
	ACADEMY_HEAL_WIPE_BODY = "« Aurais-je pu sauver le tank ? » est la bonne question — pas « pourquoi le DPS est resté dans le feu ? »\n\nSi le mana était vide, utilise des sorts plus efficaces la prochaine fois. Un wipe ne veut pas dire que tu ne peux pas soigner.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Ton premier donjon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Dis au groupe que tu apprends. Reste à portée du tank ; laisse le DPS prendre une égratignure avant de brûler le mana.\n\nEntre les pulls : boire, buff, respirer. « oom, 5 sec » est ok.",
	ACADEMY_HEAL_RAID_TITLE = "Raids et LFR (plus tard)",
	ACADEMY_HEAL_RAID_BODY = "LFR : les dégâts à l’échelle du raid sont prévisibles après un seul nettoyage. Apprenez le chronomètre de combat, pas les barres de chaque joueur.\n\nLes soins de raid utilisent le même triage : les fenêtres de temps de recharge des tanks et des raids en premier.",
	ACADEMY_HEAL_CHAT_TITLE = "Discussion de groupe",
	ACADEMY_HEAL_CHAT_BODY = "\"Apprentissage du guérisseur - J'appellerai le mana faible.\"\n\"Le tank est prioritaire - criez si tu avez besoin de respirer.\"\n\"Gros soin sur tu - surveillez ton santé.\"\n\"Oom 5 secondes entre les tirages.\"\n\"C'était de ma faute - j'en garderai plus pour le tank au prochain tirage.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Échelle d'anxiété (ordre recommandé)",
	ACADEMY_HEAL_LADDER_BODY = "1. Soigne un ami en monde ouvert\n2. Gouffres en petit groupe\n3. Donjon normal avec des amis patients\n4. Raid LFR / héroïque quand tu es prêt\n\nLes gouffres sont l'étape la plus douce vers le contenu instancié.",
	ACADEMY_HEAL_BOTH_TITLE = "Tu apprends aussi le tank ?",
	ACADEMY_HEAL_BOTH_BODY = "Utilise la piste Tank pour la file donjon ; continue de soigner en gouffres jusqu'à ce que le tank te semble familier.\n\nDeux rôles en une semaine en pug, c'est beaucoup — un rôle « principal » réduit la peur.",
	INFO_DRAWER_BODY_ACADEMY = "Académie des rôles : pistes tank/soigneur, checklist, notes donjon vs raid et lignes de chat de groupe. Les guides de niveau ajoutent l'onglet En groupe par rôle. Barre latérale : macros, consommables, guides et gouffres.",
	TAB_GUIDE_SUB_GUIDE = "Guide",
	TAB_GUIDE_SUB_LAYOUT = "Mise en page",
	TAB_LEVELING_SUB_LAYOUT = "Mise en page",
	MACROS_TYPE_INTERRUPT = "Interrompre",
	MACROS_TYPE_UTILITY = "Utilitaire",
	MACROS_CONSUMABLES_SUBTITLE = "Meilleurs choix de Midnight (flacon, pots, festin, nourriture). Survolez une ligne pour l'info-bulle de l'élément.",
	MACROS_CONS_NO_DATA = "Aucune donnée sur les consommables pour cette classe et cette spécification pour l'instant.",
