	CONS_COPY_HINT = "Clique un objet, puis Ctrl+C (les clics alternent les variantes) :",
	CONS_COPY_TT = "Clic : copier le nom (pour l'hôtel des ventes)",
	DELVE_SHARE_XLOC_HEADER_FMT = "%s a partagé des astuces de gouffre — ici dans ta langue :",
	PROFHUB_WEEKLY_HEADER = "Cette semaine",
	PROFHUB_WEEKLY_TRAINER = "quête hebdo du formateur",
	PROFHUB_WEEKLY_ESSENCES = "Mats de désenchantement dans les sacs",
	PROFHUB_GOAL_LABEL = "Objectif des conseils :",
	PROFHUB_GOAL_ALLROUND = "Polyvalent",
	PROFHUB_GOAL_GOLD = "Or",
	PROFHUB_GOAL_SELF = "Autosuffisant",
	PROFHUB_GOAL_TT_ALLROUND = "La route de départ consensuelle : un ordre équilibré pour tes premiers points — une bonne puissance d'artisanat sans t'enfermer dans une niche.",
	PROFHUB_GOAL_TT_GOLD = "Priorise les arbres dont les produits se vendent bien (enchantements, flacons, cooldowns de rouleaux, gemmes taillées). Choisis ceci si l'or est ton objectif.",
	PROFHUB_GOAL_TT_SELF = "Priorise la fabrication de tes propres consommables et équipements, et l'autosuffisance en matériaux, plutôt que la valeur marchande.",
	PROFHUB_WEEKLY_TRAINER_REQ_ENCH = "(se débloque via l'intro chez le capitaine Flaresworn — station de commandes ; demande aussi la compétence 25)",
	PROFHUB_ACCESSORY_HINT_FMT = "Astuce : %d emplacement(s) d'accessoire vide(s) — les accessoires donnent compétence et stats. D'autres artisans les fabriquent (HV : Équipement de métier).",
	INFO_DRAWER_BODY_CONSUMABLES = "Consommables Midnight par spécification (liste Wowhead). Utilise Mon personnage, < > ou recherchez (par exemple Havoc, Beast) pour prévisualiser une autre spécialisation sans tu reconnecter.",
	MACROS_MACRO_NAME_FMT = "%s",
	MACROS_COPY_SUFFIX = "Copie le texte ci-dessous dans Esc > Macros > Nouveau. Faites ensuite glisser l'icône de la macro vers un endroit de ton barre d'action (par exemple 1, 2 ou E).",
	MACROS_INTERRUPT_SUBTITLE = "Astuce de minuit : interrompt une incantation ennemie d'une seule touche. Choisis une variante ci-dessus (Focus ou Mouseover), lis la note, puis copie le texte ci-dessous.",
	MACROS_INTERRUPT_VARIANT_FOCUS = "Focus",
	MACROS_INTERRUPT_VARIANT_MOUSEOVER = "Mouseover",
	MACROS_INTERRUPT_DESC_FOCUS = "Interrompt ton focus si c'est un ennemi vivant, sinon ta cible actuelle. Mets le lanceur dangereux en focus une fois (/focus) et continue de frapper ta propre cible — cette macro ne modifie ni n'efface jamais ton focus.",
	MACROS_INTERRUPT_DESC_MOUSEOVER = "Interrompt l'ennemi sous ton curseur (fonctionne aussi sur les barres de noms et les cadres), sinon ta cible actuelle. Pas besoin de focus : survole le lanceur et appuie.",
	MACROS_UTILITY_SUBTITLE = "Astuce de minuit : macros pratiques pour tes spécifications (curseur, survol de la souris, focus). Choisissez-en un ci-dessus, lisez la note, puis copiez le texte ci-dessous.",
	MACROS_ERR_NO_UTILITY = "Aucune macro utilitaire répertoriée pour cette spécification pour le moment.",
	MACROS_ERR_NO_TYPE = "Ce type de macro n'est pas encore disponible.",
