	MACROS_ERR_EMPTY_SPEC = "Aucune macro d'interruption n'est répertoriée pour cette spécialisation (par exemple Disc/Holy Priest). Utilise ta boîte à outils de classe si nécessaire.",
	MACROS_ERR_NO_DATA = "Aucune entrée de macro d'interruption pour cette classe dans Midnight Helper pour le moment.",
