	KEYBIND_PALADIN_CAT_MAIN_ROTATION = "Constructeurs",
	KEYBIND_PALADIN_CAT_SPENDER = "Dépensiers du pouvoir sacré",
	KEYBIND_PALADIN_CAT_UTILITY = "Utilitaire",
	KEYBIND_PALADIN_CAT_DEFENSIVES = "Défenseurs",
	KEYBIND_PALADIN_CAT_BLESSINGS = "Bénédictions / mobilité",
	KEYBIND_ROLE_INTERRUPT = "Interrompre",
	KEYBIND_ROLE_MAIN_ROTATION = "Rotation principale",
	KEYBIND_ROLE_SPENDER = "Dépensier",
	KEYBIND_ROLE_UTILITY = "Utilitaire",
	KEYBIND_ROLE_DEFENSIVE = "Défensive",
	KEYBIND_ROLE_MOBILITY = "Mobilité / animal de compagnie",
	KEYBIND_ROLE_COOLDOWN = "Barre de temps de recharge",
	LAYOUT_PROTOTYPE_SUBTITLE = "Prototype — aperçu complet du clavier américain : les touches de minuit s'allument ; d'autres grisaient. Survolez ou cliquez. Les astuces de l'onglet Guide peuvent sauter ici et mettre en surbrillance une clé. Peut être retiré en toute sécurité une fois remplacé.",
	LAYOUT_KEY_UNUSED_TOOLTIP = "|cff888888Non utilisé dans la carte de liaison Midnight Hunter.|r",
	LAYOUT_KEY_MODIFIER_TOOLTIP = "|cff888888Touche Modifier — WoW gère les combos Shift/Ctrl/Alt séparément de cette carte de sorts.|r",
	LAYOUT_KEY_NAV_TOOLTIP = "|cff888888Cluster de navigation/édition — ne fait pas partie de la carte des touches de minuit.|r",
	LAYOUT_KEY_EMPTY_TOOLTIP = "|cffaaaaaaAucun rôle sur cette clé dans la carte de spécifications actuelle pour l'instant.|r",
	LAYOUT_KEY_G_OPTIONAL_TOOLTIP = "|cffaaaaaaSlot G existe dans la grille mais cette équipe le laisse souvent vide — liaison facultative.|r",
	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Déplacez ton personnage : W vers l'avant, S vers l'arrière, A/D mitrailler, souris pour tourner. WoW les utilise par défaut – gardez-les libres pour marcher.",
	LAYOUT_KEY_TAB_TOOLTIP = "L'onglet change de cible. WoW l'utilise par défaut – gardez Tab libre pour pouvoir choisir rapidement le bon ennemi au combat.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Astuce de minuit : gardez cette touche libre pour les sorts, les macros ou les combos Shift/Ctrl/Alt — même idée que les touches F allumées sur tes barres d'action.",
	LAYOUT_LEGEND = "|cff33ff61Green|r = déplacement (W A S D).\n|cffe0e070Gold|r = sorts et raccourcis sur cette carte.\n|cff59d9ffTab|r = changer de cible rapidement.\n|cff888888Grey|r = pas sur cette carte de départ.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Ouvert à partir de ton guide de mise à niveau — cette clé se trouve sur la carte de minuit.|r",
	MODULE_PLACEHOLDER = "Espace réservé au module — le contenu de \"%s\" sera monté ici.",
	INFO_DRAWER_TOGGLE_SHOW = "Informations",
	INFO_DRAWER_TOGGLE_HIDE = "Fermer",
	INFO_DRAWER_TITLE_FMT = "%s - Comment utiliser",
	INFO_DRAWER_BODY_DELVES = "Centre gouffres Midnight pour ton personnage actuel.\n\nDéplie Grande chambre forte pour le suivi hebdo des récompenses, ou Gouffres Midnight pour les monnaies de saison (clés de coffret réparées, fragments hebdo, Undercoins), Périple du gouffre / renommée et la liste des gouffres avec détection des gouffres abondants via les POI carte.\n\nNavigation : clic droit sur une ligne pour l'entrée. |cffffcc00TomTom (recommandé)|r ajoute la flèche carte et la file de waypoints. |cff00ff00Travel Assistant|r (popup si tu es loin) affiche foyer et portail hub et marche |cffffff00sans|r TomTom.\n\nTrouver le gouffre abondant le plus proche nécessite TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Liste de plusieurs personnages stockée localement par cet add-on (variables enregistrées sur ton PC, pas de synchronisation cloud Blizzard).\n\nChaque ligne répertorie les clés, les fragments, les Undercoins, l'écho des professions et un résumé compact du Grand Vault avec de riches info-bulles ; ton personnage connecté est mis en surbrillance et le tri favorise l'utilité.\n\nLes lignes sont actualisées lors de la connexion et de la devise/des événements hebdomadaires. Supprimer supprime uniquement les données instantanées du module complémentaire, jamais ton personnage WoW réel.",
	INFO_DRAWER_BODY_RARES = "Rares du monde Midnight par zone (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nChoisis une zone à gauche. Vert = fait sur ce personnage ; UP vert = vignette au spawn (probablement actif) ; tiret gris = pas sur ta carte pour l'instant.\n\nRare le plus proche = un pin ; Générer la route = tous les rares ouverts dans TomTom. Le statut UP est indicatif — ouvre la carte de zone ou rapproche-toi si doute.",
	RARES_TITLE = "Rares Midnight",
	RARES_SUBTITLE_FMT = "%d/%d faits · %d visibles sur la carte (étoile argentée)",
	RARES_EMPTY_ZONE = "Aucune liste de rares pour cette zone.",
	RARES_BTN_NEAREST = "Rare le plus proche",
	RARES_BTN_ROUTE = "Générer la route",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper :|r TomTom : rare le plus proche — %s",
	RARES_NEAREST_NONE = "Plus aucun rare incomplet dans cette zone.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant indisponible (module Gouffres non chargé).",
	RARES_ROUTE_DONE_FMT = "%d/%d rares incomplets ajoutés à TomTom. %s",
	RARES_ROUTE_ORDER_NEAR = "Ordre : le plus proche d'abord, puis le suivant à chaque étape.",
	RARES_ROUTE_ORDER_LIST = "Ordre : ordre de la liste (position indisponible).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Fait cette semaine sur ce personnage (reset mercredi).",
	RARES_TIP_UP = "Probablement actif (vignette carte au spawn).",
	RARES_TIP_DOWN = "Pas sur la carte pour l'instant — peut spawn plus tard.",
	RARES_TIP_VIGNETTE_NOTE = "Statut carte indicatif ; ouvre la carte de zone ou rapproche-toi si incertain.",
	INFO_DRAWER_BODY_SMC = "Référence de Silvermoon City pour Minuit (carte 2393). The same scroll starts with the Weekly / hub checklist when quest IDs are configured, then continues into categorized pin grids—Essential Services, Travel, Quest hubs, Profession trainers, Gathering, and more.\n\nEach location button sets Blizzard's user waypoint and, with TomTom installed, mirrors it through the slash helper (/way #2393 …).\n\nChecklist progress tints related waypoint buttons green; mettez à jour les ID de quête dans les données après les correctifs majeurs si une ligne semble erronée.",
	INFO_DRAWER_BODY_PROFESSIONS = "Suit les points de connaissance (KP) de la profession de minuit pour ton personnage actuel, ainsi que les lignes de devises lorsque le client les expose (Abondance sans alliage, Moxie de l'artisan, Éclats de Dundun hebdomadaires).\n\nEn dessous, deux colonnes répertorient les quêtes de collecte de connaissances et les livres de profession par métier : des icônes indiquent si chaque quête est terminée. Clique sur une ligne pour envoyer uniquement ce repère à TomTom (efface les autres waypoints ; Travel Assistant gère les sauts entre zones lorsque TomTom est chargé).\n\nLes boutons du bas mettent en file d'attente les repères incomplets : générer des trésors ou générer des livres (le plus proche inachevé en premier lorsque la position de ton carte est disponible).",
	INFO_DRAWER_BODY_GUIDE = "Références de mise à niveau spécification par spécification inspirées de Icy Veins : priorité des statistiques, choix d'équipement, consommables filtrés en fonction de ce que ton niveau peut réellement utiliser, lignes de conseils de sorts facultatives et conseiller de mise à niveau avec des onglets de support pour la rotation, les défenses et la concentration des talents.\n\nLorsque ton classe a une carte de touches de minuit (Chasseur / Paladin pour l'instant), les conseils peuvent afficher un bouton de clé doré - cliquez dessus pour ouvrir l'onglet Disposition et mettre en surbrillance cette touche sur le clavier. Cela relie la lecture (sur quoi appuyer) au placement (où sur le clavier), tu apprenez donc en faisant.\n\nLa barre de recherche globale comprend les mots-clés du guide et peut passer d'un onglet à l'autre de Midnight Helper ; L'aperçu tu permet de lire une autre spécialisation sans tu reconnecter pendant que Mon personnage revient à ton spécialisation active.\n\nLa visibilité de l'onglet Guide suit les paramètres : Auto (masqué au niveau 90+), Toujours afficher ou Toujours masquer.",
	INFO_DRAWER_BODY_MACROS = "Onglet Interruption : macro de coup de pied d'équipe (concentrez-vous d'abord). Onglet Utilitaire : macros de spécifications supplémentaires (sorts de curseur au sol, soins par survol de la souris et similaires) du pack d'équipe. Choisis une ligne, lisez l'astuce, copiez le texte.\n\nLes données peuvent changer après les correctifs - signalez les sorts manquants à l'équipe.",
	INFO_DRAWER_BODY_ADDONS = "Hub pour les outils facultatifs regroupés dans Midnight Helper plutôt que des téléchargements séparés.\n\nChoisis un sous-onglet en haut. Il s'agit aujourd'hui de Platynator : lien Wago, importation de chaîne de profil et galerie visuelle MF Platynator.\n\nDes panneaux de partenaires supplémentaires s'enregistrent automatiquement ici lors de la livraison des futurs modules.",
	ABOUT_WINDOW_TITLE = "À propos de Midnight Helper",
	ABOUT_VERSION_FMT = "Version installée : |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Auteurs : TwelveInchy & Claude\n\nTon compagnon Midnight tout-en-un, organisé en quatre salles — Me, Codex, Tools et Settings. Épingle tes favoris sous la barre de recherche et tape pour aller partout. Avec Cette semaine, Gouffres & Chambre forte, coachs Gouffre & Rituel, le conseiller Enchantements & Gemmes, aperçu du compte, guides Codex, professions et outils intégrés — EN / NL / DE / FR / ES / PT / IT.",
	MAIN_TITLE_VERSION_FMT = "v%s",
	BROKER_TOOLTIP_VERSION_FMT = "Version : %s",
	CHANGELOG_TITLE = "Journal des modifications de Midnight Helper",
	CHANGELOG_SUBTITLE = "Version %s",
	CHANGELOG_VERSION_FMT = "Version %s",
	CHANGELOG_CLOSE = "Fermer",
	CHANGELOG_CB_UNTIL_NEXT = "Ne plus afficher jusqu'à la prochaine version",
	CHANGELOG_CB_NEVER = "Masquer définitivement le journal des modifications",
	CHANGELOG_120_1 = "Ajout d'un panneau de conseil de mise à niveau compact avec des supports et des onglets par niveau (Rotation / Défensives / Focus Talent).",
	CHANGELOG_120_2 = "Section des consommables améliorée : affiche uniquement les éléments utilisables à ton niveau actuel et explique les prochains déverrouillages.",
	CHANGELOG_120_3 = "Ajout de la gestion des lignes d'instantanés de compte : supprimez les caractères obsolètes en toute sécurité (avec confirmation) ainsi que les rayures zébrées.",
	CHANGELOG_120_4 = "Cohérence de localisation améliorée (EN/NL) et ajout d'un glossaire de statistiques dans le guide via le nouveau ? Bouton Statistiques.",
	CHANGELOG_121_1 = "Fenêtre principale : les panneaux intérieurs respectent le cadre de dialogue doré : les ornements de coin restent visibles et la « gouttière vide » en bas/à droite à côté de la poignée de redimensionnement a disparu.",
	CHANGELOG_121_2 = "Info et À propos utilisent à nouveau les boutons standards du panneau Blizzard (même traitement que Rechercher / Mon personnage) pour une apparence cohérente sur tous les clients.",
	CHANGELOG_121_3 = "Vernis mineur seulement ; Le comportement de Delves, Vault, des guides et de la localisation est inchangé : mise à jour sécurisée.",
	CHANGELOG_122_1 = "Onglet Macros : macro d'interruption d'équipe en un clic et macros utilitaires organisées par spécification (curseur, survol de la souris, focus) : copier, coller, lire.",
	CHANGELOG_122_2 = "Prévisualisez n'importe quelle spécification sans tu reconnecter : guidez la recherche, mettez à jour les conseils de mise à niveau, la disposition du clavier et les macros pour cette classe/spécification en une seule fois.",
	CHANGELOG_122_3 = "La recherche du guide et les messages de discussion suivent ton choix de langue (/mh lang en ou nl).",
	CHANGELOG_122_4 = "Actualisation de la disposition des touches à minuit : interruption sur E, emplacements de rôles plus clairs, débordement plus intelligent (Alt, Shift, Ctrl).",
	CHANGELOG_122_5 = "Toujours en préparation : tout dans Midnight Helper est sujet à changement et à des améliorations constantes : les correctifs continueront d'arriver. Commentaires bienvenus !",
	CHANGELOG_130_1 = "Partage de conseils en groupe : envoyez des conseils d'exploration à un groupe, un raid ou une instance depuis Coach des gouffres (brief, boss, sections, copie). Testez (/sayez) en solo.",
	CHANGELOG_130_2 = "Fenêtre contextuelle des éléments de fouille : RAID-R Mini et Trovehunter's Bounty dans les fouilles : panneau automatique + icônes de mini-carte (dans la fouille uniquement ; gauche = fenêtre contextuelle, droite = utilisation).",
	CHANGELOG_130_3 = "Coach des gouffres : Maj + molette de la souris met à l'échelle l'ensemble du panneau (comme Midnight Helper). Fais glisser le coin, le bas ou le bord droit pour redimensionner ; conseils de défilement de la roue.",
	CHANGELOG_130_4 = "Pleins feux sur les boss : aperçu fiable du premier chargement, chargement du correctif de texte et zoom enregistré par boss.",
	CHANGELOG_130_5 = "Correctifs : partage de groupe uniquement lorsque tu êtes vraiment groupé ; moins d'erreurs de chat ; épeler les liens dans les conseils partagés (EN/NL).",
	CHANGELOG_130_6 = "À partir de là, les petites versions de correctifs peuvent utiliser le nom de code Valeera dans les notes : les fonctionnalités principales restent sur 1.x.",
	CHANGELOG_126_1 = "Coach des gouffres : conseils flottants pour les 11 fouilles de minuit (Overview, Route, Trash, Boss) en anglais et en néerlandais.",
	CHANGELOG_126_2 = "Pleins feux sur le boss avec aperçu 3D ; faites défiler le modèle pour zoomer/dézoomer (enregistré par boss).",
	CHANGELOG_126_3 = "Liens de sorts bleus dans les conseils ; aperçu depuis l'onglet Delves ou /mh coach ; affichage automatique dans Delve.",
	CHANGELOG_126_4 = "Fenêtre Coach déplaçable et redimensionnable avec réduction.",
	CHANGELOG_126_5 = "Corrections de la caméra Boss et des info-bulles pour la vente au détail.",
	CHANGELOG_125_1 = "Nouvel onglet Role Academy : pistes de tank et de soins avec des listes de contrôle de préparation, des conseils de tri et une rampe douce des fouilles aux donjons.",
	CHANGELOG_125_2 = "Liens rapides de Role Academy vers les macros, les consommables, les guides de mise à niveau et les fouilles.",
	CHANGELOG_125_3 = "Recherchez des mots-clés (tank, heal, academy, mentor) pour ouvrir Role Academy.",
	CHANGELOG_124_1 = "Delve et routage professionnel : repli des waypoints de la carte Blizzard lorsque TomTom n'est pas installé (SuperTrack + popup de voyage inchangé).",
	CHANGELOG_124_2 = "Aperçu du compte : devises hebdomadaires de profession dans l'info-bulle (Abondance, fragments Dundun, résumé Moxie).",
	CHANGELOG_124_3 = "Rappels de réinitialisation de Great Vault : discussion lors de la connexion, lignes d'info-bulle de la mini-carte et icône de mini-carte clignotante (configurable).",
	CHANGELOG_124_4 = "Peaufinage de l'instantané du compte : tri/filtre, niveau/ilvl, badge obsolète, cristaux de mana intacts ; routage de recherche de consommables.",
